  "file": "voice/narrator.find.shrine.3.mp3",
  "secs": 2.58,
  "text": "A shrine, glowing softly in the dark.",
  "who": "Narrator"
 },
 "narrator.find.shrine.4": {
  "file": "voice/narrator.find.shrine.4.mp3",
  "secs": 5.15,
  "text": "A god's shrine. Stop and pray, or simply pass by.",
  "who": "Narrator"
 },
 "narrator.find.stairs.1": {
  "file": "voice/narrator.find.stairs.1.mp3",
  "secs": 1.68,
  "text": "There. The stairs down.",
  "who": "Narrator"
 },
 "narrator.find.stairs.2": {
  "file": "voice/narrator.find.stairs.2.mp3",
  "secs": 2.65,
  "text": "The way down. Whenever you're ready.",
  "who": "Narrator"
 },
 "narrator.find.stairs.3": {
  "file": "voice/narrator.find.stairs.3.mp3",
  "secs": 4.96,
  "text": "Stairs. The deeper you go, the closer the Forge.",
  "who": "Narrator"
 },
 "narrator.find.stairs.4": {
  "file": "voice/narrator.find.stairs.4.mp3",
  "secs": 3.36,
  "text": "The stairs down, for when you've seen enough of this floor.",
  "who": "Narrator"
 },
 "narrator.floor.chaos-islands": {
  "file": "voice/narrator.floor.chaos-islands.mp3",
  "secs": 8.64,
  "text": "Five islands drift in the void, linked by pairs of portals. On the last, a current will carry you deeper.",
  "who": "Narrator"
 },
 "narrator.floor.crucible-gate": {
  "file": "voice/narrator.floor.crucible-gate.mp3",
  "secs": 9.81,
  "text": "Once you pass the gate, it seals behind you. Defeat all three of the Unmaker's forms, and the Forge is yours.",
  "who": "Narrator"
 },
 "narrator.floor.hall.grukk": {
  "file": "voice/narrator.floor.hall.grukk.mp3",
  "secs": 6.18,
  "text": "This is the warchief's hall. Beat Grukk, and carry his core to the gate.",
  "who": "Narrator"
 },
 "narrator.floor.hall.matron": {
  "file": "voice/narrator.floor.hall.matron.mp3",
  "secs": 6.34,
  "text": "The Matron's hall. If she begins a ritual, break it before it's finished.",
  "who": "Narrator"
 },
 "narrator.floor.hall.maw": {
  "file": "voice/narrator.floor.hall.maw.mp3",
  "secs": 5.47,
  "text": "The Deep Maw's hall. Its burrows run all through the ground here.",
  "who": "Narrator"
 },
 "narrator.floor.hall.morty": {
  "file": "voice/narrator.floor.hall.morty.mp3",
  "secs": 7.51,
  "text": "Morty's hall. While his phylactery stands, he'll keep coming back. Break it.",
  "who": "Narrator"
 },
 "narrator.floor.portal.air": {
  "file": "voice/narrator.floor.portal.air.mp3",
  "secs": 5.84,
  "text": "Something hums on this floor. A portal to the Plane of Air stands open.",
  "who": "Narrator"
 },
 "narrator.floor.portal.earth": {
  "file": "voice/narrator.floor.portal.earth.mp3",
  "secs": 6.12,
  "text": "Something hums on this floor. A portal to the Plane of Earth stands open.",
  "who": "Narrator"
 },
 "narrator.floor.portal.fire": {
  "file": "voice/narrator.floor.portal.fire.mp3",
  "secs": 6.07,
  "text": "Something hums on this floor. A portal to the Plane of Fire stands open.",
  "who": "Narrator"
 },
 "narrator.floor.portal.light": {
  "file": "voice/narrator.floor.portal.light.mp3",
  "secs": 6.48,
  "text": "Something hums on this floor. A portal to the Plane of Light stands open.",
  "who": "Narrator"
 },
 "narrator.floor.portal.shadow": {
  "file": "voice/narrator.floor.portal.shadow.mp3",
  "secs": 6.08,
  "text": "Something hums on this floor. A portal to the Plane of Shadow stands open.",
  "who": "Narrator"
 },
 "narrator.floor.portal.water": {
  "file": "voice/narrator.floor.portal.water.mp3",
  "secs": 6.2,
  "text": "Something hums on this floor. A portal to the Plane of Water stands open.",
  "who": "Narrator"
 },
 "narrator.floor.silk": {
  "file": "voice/narrator.floor.silk.mp3",
  "secs": 4.0,
  "text": "Listen. Silk, rustling somewhere in the dark.",
  "who": "Narrator"
 },
 "narrator.floor.treasure-room": {
  "file": "voice/narrator.floor.treasure-room.mp3",
  "secs": 7.7,
  "text": "A quiet treasure room, with a Forge. Gather your supplies and make ready. Chaos lies ahead.",
  "who": "Narrator"
 },
 "narrator.intro.again.1": {
  "file": "voice/narrator.intro.again.1.mp3",
  "secs": 9.08,
  "text": "The Forge is still cold, and the Unmaker still waits beyond the void. The gods have chosen another hero.",
  "who": "Narrator"
 },
 "narrator.intro.again.2": {
  "file": "voice/narrator.intro.again.2.mp3",
  "secs": 8.23,
  "text": "Another hero, chosen by the gods. Somewhere far below, the Unmaker is waiting.",
  "who": "Narrator"
 },
 "narrator.intro.again.3": {
  "file": "voice/narrator.intro.again.3.mp3",
  "secs": 8.32,
  "text": "The planar Forge is dark, and the Unmaker hungers for it. Go deep. The gods are with you.",
  "who": "Narrator"
 },
 "narrator.intro.first": {
  "file": "voice/narrator.intro.first.mp3",
  "secs": 21.68,
  "text": "Long ago, the world was forged from six elements, at the planar Forge. Now the Unmaker has come from outside reality to claim it, and the Forge's fire has gone out. The gods have chosen someone to go down and light it again. Apparently, they chose you.",
  "who": "Narrator"
 },
 "narrator.tutorial.around": {
  "file": "voice/narrator.tutorial.around.mp3",
  "secs": 14.01,
  "text": "Your portrait shows your hero, and your bag holds your things. The compass explores for you, and stops when danger appears. The Journal explains everything you discover.",
  "who": "Narrator"
 },
 "narrator.tutorial.bag": {
  "file": "voice/narrator.tutorial.bag.mp3",
  "secs": 12.21,
  "text": "Something for your bag! Looking through it costs no time. Careful with gear you haven't identified. Some of it is cursed, and won't come off once it's on.",
  "who": "Narrator"
 },
 "narrator.tutorial.class": {
  "file": "voice/narrator.tutorial.class.mp3",
  "secs": 9.45,
  "text": "Now choose how you fight. Your class decides your starting gear and your skills. A Cleric must choose a god, too.",
  "who": "Narrator"
 },
 "narrator.tutorial.core": {
  "file": "voice/narrator.tutorial.core.mp3",
  "secs": 8.97,
  "text": "A boss core raises how strong your elements can grow. You can even fuse a mote with it now, no Forge needed.",
  "who": "Narrator"
 },
 "narrator.tutorial.cursed": {
  "file": "voice/narrator.tutorial.cursed.mp3",
  "secs": 11.1,
  "text": "Oh dear. That's cursed. It's weaker than it should be, and it won't come off. Upgrading it at a Forge will cleanse it, and so will the right sigil.",
  "who": "Narrator"
 },
 "narrator.tutorial.forge-found": {
  "file": "voice/narrator.tutorial.forge-found.mp3",
  "secs": 10.82,
  "text": "A Forge, still burning, even down here. At a Forge you can take in the power of the elements, strengthen your gear, and craft sigils.",
  "who": "Narrator"
 },
 "narrator.tutorial.forge.craft": {
  "file": "voice/narrator.tutorial.forge.craft.mp3",
  "secs": 7.84,
  "text": "Craft your own sigils from motes and essence. A sigil you make yourself is never a mystery.",
  "who": "Narrator"
 },
 "narrator.tutorial.forge.enchant": {
  "file": "voice/narrator.tutorial.forge.enchant.mp3",
  "secs": 7.36,
  "text": "Spend a mote to enchant the gear you're wearing with its element. It works best when that element is one of your own.",
  "who": "Narrator"
 },
 "narrator.tutorial.forge.fuse": {
  "file": "voice/narrator.tutorial.forge.fuse.mp3",
  "secs": 16.24,
  "text": "Fuse a mote to take its element into yourself, for good. You can hold two elements, but never opposites, like Fire and Water. Grow both strong enough, and you'll unlock a power that uses both.",
  "who": "Narrator"
 },
 "narrator.tutorial.forge.recycle": {
  "file": "voice/narrator.tutorial.forge.recycle.mp3",
  "secs": 3.95,
  "text": "Melt down gear you don't need, and turn it into essence.",
  "who": "Narrator"
 },
 "narrator.tutorial.forge.upgrade": {
  "file": "voice/narrator.tutorial.forge.upgrade.mp3",
  "secs": 8.24,
  "text": "Spend essence to make the gear you're wearing stronger. If a piece is cursed, upgrading cleanses it instead.",
  "who": "Narrator"
 },
 "narrator.tutorial.god": {
  "file": "voice/narrator.tutorial.god.mp3",
  "secs": 11.23,
  "text": "Earn your god's piety to rise through their ranks and unlock boons and prayers. Most prayers cost favour, which you'll find under your hunger.",
  "who": "Narrator"
 },
 "narrator.tutorial.hungry": {
  "file": "voice/narrator.tutorial.hungry.mp3",
  "secs": 8.42,
  "text": "Your stomach is growling. Eat something soon. A hungry hero can't rest, and a starving one starts losing health.",
  "who": "Narrator"
 },
 "narrator.tutorial.level": {
  "file": "voice/narrator.tutorial.level.mp3",
  "secs": 8.24,
  "text": "You've gained a level! The gold number on your portrait is points to spend. Put them where you need them most.",
  "who": "Narrator"
 },
 "narrator.tutorial.play": {
  "file": "voice/narrator.tutorial.play.mp3",
  "secs": 16.72,
  "text": "Down here, nothing moves until you do. Walk into an enemy to attack it, and rest when none are in sight. Fall in battle, and the run is over for good. Now, find the stairs down.",
  "who": "Narrator"
 },
 "narrator.tutorial.race": {
  "file": "voice/narrator.tutorial.race.mp3",
  "secs": 11.49,
  "text": "Every hero starts somewhere. Your race shapes your strengths from the very first step. If you choose the Fae, pick your court as well.",
  "who": "Narrator"
 },
 "narrator.tutorial.shrine": {
  "file": "voice/narrator.tutorial.shrine.mp3",
  "secs": 12.92,
  "text": "A shrine to one of the gods. Here you can learn their rule, swear yourself to them, or pray. Your own god will restore your favour here, once each floor.",
  "who": "Narrator"
 },
 "narrator.tutorial.sigils": {
  "file": "voice/narrator.tutorial.sigils.mp3",
  "secs": 13.84,
  "text": "That's a sigil, a spell you can cast once. If you don't know what it is, casting it will tell you, for better or worse. Some gods forbid them, so check your faith first.",
  "who": "Narrator"
 },
 "narrator.tutorial.stairs": {
  "file": "voice/narrator.tutorial.stairs.mp3",
  "secs": 5.0,
  "text": "The stairs down. Go when you're ready. You can always come back up.",
  "who": "Narrator"
 },
 "narrator.unmaker.defeated": {
  "file": "voice/narrator.unmaker.defeated.mp3",
  "secs": 12.99,
  "text": "The Unmaker is undone, and the void has lost its grip. Before you stands the planar Forge, cold for so long. Now, at last, it wakes.",
  "who": "Narrator"
 },
 "narrator.victory": {
  "file": "voice/narrator.victory.mp3",
  "secs": 12.75,
  "text": "The Forge burns once more, and the world is whole again. The gods chose well. Go on, then. Go home a hero.",
  "who": "Narrator"
 },
 "stone-f.normal.biome.caverns": {
  "file": "voice/stone-f.normal.biome.caverns.mp3",
  "secs": 9.1,
  "text": "A garden of crystals, growing from the stone. Whatever is tunnelling down here, I'll stand my ground."
 },
 "stone-f.normal.biome.chaos": {
  "file": "voice/stone-f.normal.biome.chaos.mp3",
  "secs": 7.81,
  "text": "Stone should never float. This is the Unmaker's doing, and I'm here to put it right."
 },
 "stone-f.normal.biome.crypt": {
  "file": "voice/stone-f.normal.biome.crypt.mp3",
  "secs": 8.08,
  "text": "When this is over, I'll plant flowers for the dead. First, I'll lay them back to rest."
 },
 "stone-f.normal.biome.underdark": {
  "file": "voice/stone-f.normal.biome.underdark.mp3",
  "secs": 8.85,
  "text": "Spiders and dark elves, and no sun at all. I'm slow but sure, and I won't stop."
 },
 "stone-f.normal.class.cleric": {
  "file": "voice/stone-f.normal.class.cleric.mp3",
  "secs": 3.06,
  "text": "Blessed, like spring soil."
 },
 "stone-f.normal.class.fighter": {
  "file": "voice/stone-f.normal.class.fighter.mp3",
  "secs": 2.25,
  "text": "Strong as stone!"
 },
 "stone-f.normal.class.mage": {
  "file": "voice/stone-f.normal.class.mage.mp3",
  "secs": 2.37,
  "text": "Earthy magic? Lovely!"
 },
 "stone-f.normal.class.scoundrel": {
  "file": "voice/stone-f.normal.class.scoundrel.mp3",
  "secs": 2.53,
  "text": "Quiet as moss."
 },
 "stone-f.normal.class.tourist": {
  "file": "voice/stone-f.normal.class.tourist.mp3",
  "secs": 1.82,
  "text": "A garden holiday!"
 },
 "stone-f.normal.death": {
  "file": "voice/stone-f.normal.death.mp3",
  "secs": 1.5,
  "text": "Ohhh!"
 },
 "stone-f.normal.hurt.1": {
  "file": "voice/stone-f.normal.hurt.1.mp3",
  "secs": 0.25,
  "text": "Hngh!"
 },
 "stone-f.normal.hurt.2": {
  "file": "voice/stone-f.normal.hurt.2.mp3",
  "secs": 0.25,
  "text": "Ugh!"
 },
 "stone-f.normal.hurt.3": {
  "file": "voice/stone-f.normal.hurt.3.mp3",
  "secs": 0.25,
  "text": "Agh!"
 },
 "stone-f.normal.infuse.earth": {
  "file": "voice/stone-f.normal.infuse.earth.mp3",
  "secs": 8.76,
  "text": "Stoneskin, from the good earth that raised me. Now I'm as hard to move as a hill."
 },
 "stone-f.normal.infuse.fire": {
  "file": "voice/stone-f.normal.infuse.fire.mp3",
  "secs": 7.92,
  "text": "Fire is no friend to leaves. I'll carry it carefully, and save it for the monsters."
 },
 "stone-f.normal.infuse.light": {
  "file": "voice/stone-f.normal.infuse.light.mp3",
  "secs": 8.72,
  "text": "Light, warm as the summer sun. I'll bring it down on anything that hurts this world."
 },
 "stone-f.normal.infuse.shadow": {
  "file": "voice/stone-f.normal.infuse.shadow.mp3",
  "secs": 6.74,
  "text": "Shadow, cool as the shade of an old oak. It heals me while I fight."
 },
 "stone-f.normal.infuse.water": {
  "file": "voice/stone-f.normal.infuse.water.mp3",
  "secs": 8.24,
  "text": "Ice armour, cold as a frosty morning. Underneath, my heart is as warm as ever."
 },
 "stone-f.normal.plane.air": {
  "file": "voice/stone-f.normal.plane.air.mp3",
  "secs": 8.85,
  "text": "This wind feels all wrong, tugging at every leaf. Still, I stay where I'm planted."
 },
 "stone-f.normal.plane.earth": {
  "file": "voice/stone-f.normal.plane.earth.mp3",
  "secs": 8.74,
  "text": "Home at last. Falling rocks don't frighten me, because I know how stone moves."
 },
 "stone-f.normal.plane.fire": {
  "file": "voice/stone-f.normal.plane.fire.mp3",
  "secs": 8.78,
  "text": "Melted rock below, and burning stones above. I'll take it steady, and keep an eye on the roof."
 },
 "stone-f.normal.plane.light": {
  "file": "voice/stone-f.normal.plane.light.mp3",
  "secs": 7.73,
  "text": "I love the sun, but this light is fierce. The glowing stones are the ones to watch."
 },
 "stone-f.normal.plane.shadow": {
  "file": "voice/stone-f.normal.plane.shadow.mp3",
  "secs": 7.79,
  "text": "As dark as deep soil. Seeds grow in the dark, and so can I."
 },
 "stone-f.normal.plane.water": {
  "file": "voice/stone-f.normal.plane.water.mp3",
  "secs": 6.94,
  "text": "This water isn't gentle like rain. Where it runs deep, it pulls you down."
 },
 "stone-f.normal.select": {
  "file": "voice/stone-f.normal.select.mp3",
  "secs": 1.9,
  "text": "Steady, and ready!"
 },
 "stone-f.normal.start": {
  "file": "voice/stone-f.normal.start.mp3",
  "secs": 9.07,
  "text": "Every flower and stone in the world is counting on me. Step by step, I'll reach the Forge."
 },
 "stone-f.tourist.biome.caverns": {
  "file": "voice/stone-f.tourist.biome.caverns.mp3",
  "secs": 9.54,
  "text": "Glowing mushrooms! And crystals! This is the best garden tour I've ever been on."
 },
 "stone-f.tourist.biome.chaos": {
  "file": "voice/stone-f.tourist.biome.chaos.mp3",
  "secs": 6.69,
  "text": "Floating islands, each with its own little garden! I want to visit every one."
 },
 "stone-f.tourist.biome.crypt": {
  "file": "voice/stone-f.tourist.biome.crypt.mp3",
  "secs": 6.81,
  "text": "Graveyard flowers! I'll press one for my holiday book. Thank you, skeletons!"
 },
 "stone-f.tourist.biome.underdark": {
  "file": "voice/stone-f.tourist.biome.underdark.mp3",
  "secs": 7.03,
  "text": "Lava rocks are ever so pretty. Ow, hot! I'll pick that one up later."
 },
 "stone-f.tourist.infuse.earth": {
  "file": "voice/stone-f.tourist.infuse.earth.mp3",
  "secs": 6.75,
  "text": "Stoneskin! I feel like the prettiest rock in my whole collection."
 },
 "stone-f.tourist.infuse.fire": {
  "file": "voice/stone-f.tourist.infuse.fire.mp3",
  "secs": 8.48,
  "text": "Burning touch? Oh, careful! Pressed flowers and fire do not mix."
 },
 "stone-f.tourist.infuse.light": {
  "file": "voice/stone-f.tourist.infuse.light.mp3",
  "secs": 7.16,
  "text": "Glowing! Like a sunflower at midday. Every plant is turning to look at me."
 },
 "stone-f.tourist.infuse.shadow": {
  "file": "voice/stone-f.tourist.infuse.shadow.mp3",
  "secs": 6.48,
  "text": "Shadow power. A bit gloomy, but it goes nicely with my green dress."
 },
 "stone-f.tourist.infuse.water": {
  "file": "voice/stone-f.tourist.infuse.water.mp3",
  "secs": 6.31,
  "text": "Ice armour! Like frost on a rose. I'd better not press this one."
 },
 "stone-f.tourist.plane.air": {
  "file": "voice/stone-f.tourist.plane.air.mp3",
  "secs": 7.91,
  "text": "Oh, this wind! My pressed flowers are flying off, one by one. Bye, buttercups!"
 },
 "stone-f.tourist.plane.earth": {
  "file": "voice/stone-f.tourist.plane.earth.mp3",
  "secs": 8.74,
  "text": "A holiday at home! I won't take any rocks, I promise. Well, maybe just one."
 },
 "stone-f.tourist.plane.fire": {
  "file": "voice/stone-f.tourist.plane.fire.mp3",
  "secs": 7.39,
  "text": "Too hot for flowers here. Oh, but look at that lovely shiny black rock!"
 },
 "stone-f.tourist.plane.light": {
  "file": "voice/stone-f.tourist.plane.light.mp3",
  "secs": 6.94,
  "text": "So sunny! Sunglasses down. Now the flowers in my hair are sunbathing too."
 },
 "stone-f.tourist.plane.shadow": {
  "file": "voice/stone-f.tourist.plane.shadow.mp3",
  "secs": 8.03,
  "text": "Too dark for flowers, but those violet crystals are lovely. Like purple crocuses!"
 },
 "stone-f.tourist.plane.water": {
  "file": "voice/stone-f.tourist.plane.water.mp3",
  "secs": 7.67,
  "text": "A sea garden! Look at all the seaweed. Ooh, and a whole beach of pebbles!"
 },
 "stone-f.tourist.start": {
  "file": "voice/stone-f.tourist.start.mp3",
  "secs": 7.16,
  "text": "Sunglasses, flower press, and an empty bag for pretty rocks. Off we go!"
 },
 "stone-m.normal.biome.caverns": {
  "file": "voice/stone-m.normal.biome.caverns.mp3",
  "secs": 9.92,
  "text": "These stones are older than any tree, and they're warning me. Something huge is close."
 },
 "stone-m.normal.biome.chaos": {
  "file": "voice/stone-m.normal.biome.chaos.mp3",
  "secs": 7.35,
  "text": "Nothing grows in the void, not one leaf. I won't let it swallow the world."
 },
 "stone-m.normal.biome.crypt": {
  "file": "voice/stone-m.normal.biome.crypt.mp3",
  "secs": 5.74,
  "text": "The bones won't lie still. I'll walk softly, and I won't run."
 },
 "stone-m.normal.biome.underdark": {
  "file": "voice/stone-m.normal.biome.underdark.mp3",
  "secs": 7.33,
  "text": "Webs above me, fire below. I'll be quiet as a root, and just as stubborn."
 },
 "stone-m.normal.class.cleric": {
  "file": "voice/stone-m.normal.class.cleric.mp3",
  "secs": 1.8,
  "text": "The roots will pray with me."
 },
 "stone-m.normal.class.fighter": {
  "file": "voice/stone-m.normal.class.fighter.mp3",
  "secs": 1.82,
  "text": "A sword? Gently, then."
 },
 "stone-m.normal.class.mage": {
  "file": "voice/stone-m.normal.class.mage.mp3",
  "secs": 2.01,
  "text": "Earth magic. I like it."
 },
 "stone-m.normal.class.scoundrel": {
  "file": "voice/stone-m.normal.class.scoundrel.mp3",
  "secs": 1.46,
  "text": "Quiet, like a fox."
 },
 "stone-m.normal.class.tourist": {
  "file": "voice/stone-m.normal.class.tourist.mp3",
  "secs": 1.86,
  "text": "Shh. A nature walk."
 },
 "stone-m.normal.death": {
  "file": "voice/stone-m.normal.death.mp3",
  "secs": 0.9,
  "text": "Ahhh!"
 },
 "stone-m.normal.hurt.1": {
  "file": "voice/stone-m.normal.hurt.1.mp3",
  "secs": 0.25,
  "text": "Hngh!"
 },
 "stone-m.normal.hurt.2": {
